CREATE TABLE pesagens_animais (id BIGSERIAL PRIMARY KEY, propriedade_id BIGINT NOT NULL REFERENCES propriedades(id),animal_id BIGINT NOT NULL REFERENCES animais(id),data_pesagem DATE NOT NULL,peso_kg NUMERIC(10,3) NOT NULL CHECK(peso_kg>0),observacao VARCHAR(500));
CREATE INDEX ix_pesagens_animal_data ON pesagens_animais(animal_id,data_pesagem DESC);
CREATE TABLE safras (id BIGSERIAL PRIMARY KEY,propriedade_id BIGINT NOT NULL REFERENCES propriedades(id),talhao_id BIGINT NOT NULL REFERENCES talhoes(id),cultura VARCHAR(100) NOT NULL,variedade VARCHAR(100),identificacao VARCHAR(100) NOT NULL,data_inicio DATE NOT NULL,data_fim_prevista DATE,area_plantada_ha NUMERIC(12,4) NOT NULL CHECK(area_plantada_ha>0),status VARCHAR(20) NOT NULL DEFAULT 'PLANEJADA',observacoes TEXT,UNIQUE(propriedade_id,identificacao),CHECK(data_fim_prevista IS NULL OR data_fim_prevista>=data_inicio));
CREATE TABLE itens_estoque (id BIGSERIAL PRIMARY KEY,propriedade_id BIGINT NOT NULL REFERENCES propriedades(id),codigo VARCHAR(80),nome VARCHAR(160) NOT NULL,categoria VARCHAR(80) NOT NULL,unidade_medida VARCHAR(30) NOT NULL,estoque_minimo NUMERIC(14,3) NOT NULL DEFAULT 0 CHECK(estoque_minimo>=0),ativo BOOLEAN NOT NULL DEFAULT TRUE,UNIQUE(propriedade_id,nome),UNIQUE(propriedade_id,codigo));
CREATE TABLE partidas_estoque (id BIGSERIAL PRIMARY KEY,propriedade_id BIGINT NOT NULL REFERENCES propriedades(id),item_estoque_id BIGINT NOT NULL REFERENCES itens_estoque(id),codigo_lote VARCHAR(100),data_entrada DATE NOT NULL,data_validade DATE,quantidade_inicial NUMERIC(14,3) NOT NULL CHECK(quantidade_inicial>0),quantidade_atual NUMERIC(14,3) NOT NULL CHECK(quantidade_atual>=0),valor_unitario_origem NUMERIC(14,4) NOT NULL CHECK(valor_unitario_origem>=0),CHECK(data_validade IS NULL OR data_validade>=data_entrada));
CREATE TABLE movimentacoes_estoque (id BIGSERIAL PRIMARY KEY,propriedade_id BIGINT NOT NULL REFERENCES propriedades(id),partida_id BIGINT NOT NULL REFERENCES partidas_estoque(id),tipo VARCHAR(20) NOT NULL CHECK(tipo IN ('ENTRADA','USO','DESCARTE')),quantidade NUMERIC(14,3) NOT NULL CHECK(quantidade>0),data_operacao DATE NOT NULL,motivo VARCHAR(300) NOT NULL,valor_total_origem NUMERIC(14,4));
CREATE INDEX ix_mov_estoque_partida_data ON movimentacoes_estoque(partida_id,data_operacao);
